def public_card(card):
    return {k: v for k, v in card.items() if k not in ("answer", "tolerance")}

def find_lesson(slug):
    for ui, unit in enumerate(UNITS):
        for li, lesson in enumerate(unit[4]):
            if lesson[0] == slug:
                return ui, li, lesson
    return None
